use vstd::prelude::*;

verus! {
    /// Given a non‐empty array `list` of i32 and an index `n` with
    /// 0 < n < list.len(), produce a new array which is `list` rotated
    /// to the left by `n` positions.
    fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
        requires
            list.len() > 0,
            n < list.len(),
        ensures
            new_list.len() == list.len() &&
            // for each position k in 0..list.len(), new_list[k] is
            // list[n + k] if k < list.len() - n, else list[k - (list.len() - n)]
            forall |k: usize| k < list.len() ==>
                if k < list.len() - n {
                    new_list[k] == list[n + k]
                } else {
                    new_list[k] == list[k - (list.len() - n)]
                }
    {
        let L = list.len();
        let mut new_list: Vec<i32> = Vec::new();
        new_list.reserve(L);

        // First, append list[n..L]
        let mut i: usize = n;
        while i < L
            invariant n <= i && i <= L
            invariant new_list.len() == i - n
            invariant forall |k: usize| k < new_list.len() ==>
                new_list[k] == list[n + k]
            decreases L - i
        {
            new_list.push(list[i]);
            i = i + 1;
        }

        // Then, append list[0..n]
        let mut j: usize = 0;
        while j < n
            invariant j <= n
            invariant new_list.len() == (L - n) + j
            invariant forall |k: usize| k < L - n ==>
                new_list[k] == list[n + k]
            invariant forall |k: usize| k < j ==>
                new_list[(L - n) + k] == list[k]
            decreases n - j
        {
            new_list.push(list[j]);
            j = j + 1;
        }

        // Now new_list.len() == L, and the two invariants together
        // imply the overall rotation property.
        assert(new_list.len() == L);
        assert(forall |k: usize| k < L ==>
            if k < L - n {
                new_list[k] == list[n + k]
            } else {
                new_list[k] == list[k - (L - n)]
            });

        new_list
    }
}

